50	    public ReleaseView create(CreateReleaseRequest request) {
51	        if (request.fromVersion().equals(request.toVersion())) {
52	            throw ApiException.badRequest("SAME_VERSION", "目标版本必须与来源版本不同");
53	        }
54	        int sampleFloor = request.effectiveSampleFloor();
55	        int threshold = request.effectiveFailureThresholdPercent();
56	        String fingerprint = String.join("|", "release.create", request.model(), request.fromVersion(),
57	                request.toVersion(), String.valueOf(request.ratio()), String.valueOf(sampleFloor),
58	                String.valueOf(threshold));
