1	package com.example.starter.firmware.service;
2	
3	import com.example.starter.firmware.error.ApiException;
4	import com.example.starter.firmware.repo.IdempotencyRepository;
5	import com.fasterxml.jackson.databind.ObjectMapper;
6	import org.springframework.dao.DuplicateKeyException;
7	import org.springframework.stereotype.Service;
8	import org.springframework.transaction.support.TransactionTemplate;
9	
10	import java.util.function.Supplier;
11	
12	/**
13	 * 写操作幂等执行器：同一事务内完成业务变更与去重记录写入，原子提交。
14	 * 同键同参重放原成功结果；同键异参返回 409；业务失败回滚，不占键。
15	 * 同 requestId 的执行通过分段锁串行化，避免并发下检查与写入之间的竞态；
16	 * 数据库唯一约束作为最终兜底。
17	 */
18	@Service
19	public class IdempotencyService {
20	
21	    /**
22	     * 内部信号：并发下同键插入冲突，回滚当前事务后改为重放已提交记录。
23	     */
24	    private static final class ReplayNeededException extends RuntimeException {
25	    }
26	
27	    private static final int LOCK_STRIPES = 256;
28	
29	    private final Object[] locks = new Object[LOCK_STRIPES];
30	
31	    private final IdempotencyRepository repository;
32	    private final TransactionTemplate transactionTemplate;
33	    private final ObjectMapper objectMapper;
34	
35	    public IdempotencyService(IdempotencyRepository repository, TransactionTemplate transactionTemplate,
36	                              ObjectMapper objectMapper) {
37	        this.repository = repository;
38	        this.transactionTemplate = transactionTemplate;
39	        this.objectMapper = objectMapper;
40	        for (int i = 0; i < LOCK_STRIPES; i++) {
41	            locks[i] = new Object();
42	        }
43	    }
44	
45	    public <T> T execute(String requestId, String api, String fingerprint, Supplier<T> action, Class<T> type) {
46	        synchronized (locks[Math.floorMod(requestId.hashCode(), LOCK_STRIPES)]) {
47	            try {
48	                return transactionTemplate.execute(status -> executeInTransaction(requestId, api, fingerprint, action, type));
49	            } catch (ReplayNeededException e) {
50	                return replayCommitted(requestId, fingerprint, type);
51	            }
52	        }
53	    }
54	
55	    private <T> T executeInTransaction(String requestId, String api, String fingerprint,
56	                                       Supplier<T> action, Class<T> type) {
57	        var existing = repository.find(requestId);
58	        if (existing.isPresent()) {
59	            return replay(existing.get(), fingerprint, type);
60	        }
61	        T result = action.get();
62	        try {
63	            repository.insert(requestId, api, fingerprint, writeJson(result));
64	        } catch (DuplicateKeyException e) {
65	            throw new ReplayNeededException();
66	        }
67	        return result;
68	    }
69	
70	    private <T> T replayCommitted(String requestId, String fingerprint, Class<T> type) {
71	        var record = repository.find(requestId)
72	                .orElseThrow(() -> new IllegalStateException("幂等记录缺失: " + requestId));
73	        return replay(record, fingerprint, type);
74	    }
75	
76	    private <T> T replay(IdempotencyRepository.IdempotencyRecord record, String fingerprint, Class<T> type) {
77	        if (!record.fingerprint().equals(fingerprint)) {
78	            throw ApiException.conflict("REQUEST_ID_CONFLICT", "requestId 已被不同参数的请求占用");
79	        }
80	        try {
81	            return objectMapper.readValue(record.responseBody(), type);
82	        } catch (Exception e) {
83	            throw new IllegalStateException("幂等响应反序列化失败", e);
84	        }
85	    }
86	
87	    private String writeJson(Object value) {
88	        try {
89	            return objectMapper.writeValueAsString(value);
90	        } catch (Exception e) {
91	            throw new IllegalStateException("幂等响应序列化失败", e);
92	        }
93	    }
94	}
