1	package com.example.starter.firmware.repo;
2	
3	import com.example.starter.firmware.domain.ReceiptResult;
4	import com.example.starter.firmware.domain.RolloutTask;
5	import com.example.starter.firmware.domain.TaskStatus;
6	import org.springframework.jdbc.core.JdbcTemplate;
7	import org.springframework.jdbc.core.RowMapper;
8	import org.springframework.jdbc.support.GeneratedKeyHolder;
9	import org.springframework.jdbc.support.KeyHolder;
10	import org.springframework.stereotype.Repository;
11	
12	import java.sql.PreparedStatement;
13	import java.util.List;
14	import java.util.Optional;
15	
16	/**
17	 * 投放任务数据访问。同设备同发布单由唯一约束 uk_task_release_device 保证最多一条。
18	 */
19	@Repository
20	public class TaskRepository {
21	
22	    private static final RowMapper<RolloutTask> MAPPER = (rs, rowNum) -> {
23	        String firstResult = rs.getString("first_result");
24	        return new RolloutTask(rs.getLong("id"), rs.getLong("release_id"), rs.getString("device_id"),
25	                TaskStatus.valueOf(rs.getString("status")),
26	                firstResult == null ? null : ReceiptResult.valueOf(firstResult));
27	    };
28	
29	    private static final String COLUMNS = "id, release_id, device_id, status, first_result";
30	
31	    private final JdbcTemplate jdbc;
32	
33	    public TaskRepository(JdbcTemplate jdbc) {
34	        this.jdbc = jdbc;
35	    }
36	
37	    public long insert(long releaseId, String deviceId) {
38	        KeyHolder keyHolder = new GeneratedKeyHolder();
39	        jdbc.update(con -> {
40	            PreparedStatement ps = con.prepareStatement(
41	                    "INSERT INTO rollout_task (release_id, device_id, status) VALUES (?, ?, 'PENDING')",
42	                    new String[]{"id"});
43	            ps.setLong(1, releaseId);
44	            ps.setString(2, deviceId);
45	            return ps;
46	        }, keyHolder);
47	        return keyHolder.getKey().longValue();
48	    }
49	
50	    public Optional<RolloutTask> findById(long id) {
51	        return jdbc.query("SELECT " + COLUMNS + " FROM rollout_task WHERE id = ?", MAPPER, id)
52	                .stream().findFirst();
53	    }
54	
55	    public Optional<RolloutTask> findByIdForUpdate(long id) {
56	        return jdbc.query("SELECT " + COLUMNS + " FROM rollout_task WHERE id = ? FOR UPDATE", MAPPER, id)
57	                .stream().findFirst();
58	    }
59	
60	    public Optional<RolloutTask> findByReleaseAndDevice(long releaseId, String deviceId) {
61	        return jdbc.query("SELECT " + COLUMNS + " FROM rollout_task WHERE release_id = ? AND device_id = ?",
62	                MAPPER, releaseId, deviceId).stream().findFirst();
63	    }
64	
65	    public void complete(long id, ReceiptResult result) {
66	        jdbc.update("UPDATE rollout_task SET status = ?, first_result = ?, updated_at = CURRENT_TIMESTAMP"
67	                + " WHERE id = ?", result.name(), result.name(), id);
68	    }
69	
70	    public int cancelPendingByRelease(long releaseId) {
71	        return jdbc.update("UPDATE rollout_task SET status = 'CANCELLED', updated_at = CURRENT_TIMESTAMP"
72	                + " WHERE release_id = ? AND status = 'PENDING'", releaseId);
73	    }
74	
75	    public List<RolloutTask> findByRelease(long releaseId, TaskStatus statusFilter) {
76	        if (statusFilter == null) {
77	            return jdbc.query("SELECT " + COLUMNS + " FROM rollout_task WHERE release_id = ? ORDER BY id",
78	                    MAPPER, releaseId);
79	        }
80	        return jdbc.query("SELECT " + COLUMNS + " FROM rollout_task WHERE release_id = ? AND status = ? ORDER BY id",
81	                MAPPER, releaseId, statusFilter.name());
